CREATE COLUMN TABLE "TEST_AP"."OAIB" ("AlertCode" INTEGER CS_INT NOT NULL , "UserSign" SMALLINT CS_INT NOT NULL , "Opened" NVARCHAR(1) DEFAULT 'N', "RecDate" LONGDATE CS_LONGDATE, "RecTime" SMALLINT CS_INT, "WasRead" NVARCHAR(1) DEFAULT 'N', "Deleted" NVARCHAR(1) DEFAULT 'N', "Failed" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AlertCode", "UserSign")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "OAIB_USER" ON "TEST_AP"."OAIB" ( "UserSign" ASC );
CREATE INDEX "OAIB_READ" ON "TEST_AP"."OAIB" ( "WasRead" ASC );
CREATE INDEX "OAIB_DELETED" ON "TEST_AP"."OAIB" ( "Deleted" ASC )